CREATE TABLE images(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','ready','failed','deleted')),object_key TEXT NOT NULL,thumb_key TEXT NOT NULL,width INTEGER NOT NULL DEFAULT 0,height INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,original_bytes INTEGER NOT NULL DEFAULT 0,mime TEXT NOT NULL,reservation INTEGER NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,deleted_at TEXT,UNIQUE(user_id,request_id),UNIQUE(id,user_id));
CREATE INDEX images_user_state ON images(user_id,state);
CREATE TRIGGER images_quota BEFORE INSERT ON images BEGIN SELECT CASE WHEN (SELECT used_bytes+reserved_bytes+NEW.reservation FROM storage_usage WHERE user_id=NEW.user_id)>209715200 THEN RAISE(ABORT,'quota_exceeded') END; END;
CREATE TRIGGER images_reserve AFTER INSERT ON images BEGIN UPDATE storage_usage SET reserved_bytes=reserved_bytes+NEW.reservation WHERE user_id=NEW.user_id; END;
CREATE TRIGGER images_ready AFTER UPDATE OF state ON images WHEN OLD.state='pending' AND NEW.state='ready' BEGIN UPDATE storage_usage SET reserved_bytes=reserved_bytes-OLD.reservation,used_bytes=used_bytes+NEW.bytes WHERE user_id=NEW.user_id; END;
CREATE TRIGGER images_failed AFTER UPDATE OF state ON images WHEN OLD.state='pending' AND NEW.state='failed' BEGIN UPDATE storage_usage SET reserved_bytes=reserved_bytes-OLD.reservation WHERE user_id=NEW.user_id; END;
CREATE TRIGGER images_reclaim AFTER DELETE ON images WHEN OLD.state IN ('ready','deleted') BEGIN UPDATE storage_usage SET used_bytes=used_bytes-OLD.bytes WHERE user_id=OLD.user_id; END;
CREATE TABLE image_refs(image_id TEXT NOT NULL,user_id TEXT NOT NULL,ref_type TEXT NOT NULL,ref_id TEXT NOT NULL,PRIMARY KEY(image_id,ref_type,ref_id),FOREIGN KEY(image_id,user_id) REFERENCES images(id,user_id));
CREATE TRIGGER ref_ready BEFORE INSERT ON image_refs BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM images WHERE id=NEW.image_id AND user_id=NEW.user_id AND state='ready') THEN RAISE(ABORT,'image_unavailable') END; END;
CREATE TRIGGER image_no_delete BEFORE UPDATE OF state ON images WHEN NEW.state='deleted' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM image_refs WHERE image_id=NEW.id) THEN RAISE(ABORT,'image_referenced') END; END;
